-- Free daily meme quiz + attendance streak.
-- The retired Plus "global daily challenge" (get_plus_global_daily_challenge)
-- had the streak walk we want, but it is gated on an active Plus entitlement and only
-- schedules memes with four reviewed translations, so it cannot serve free
-- users. This migration keeps the same KST-boundary streak logic in a new,
-- ungated pair of RPCs. The question itself is generated by /api/daily-quiz;
-- the DB only records that a signed-in user answered today's quiz.

create table if not exists public.daily_meme_quiz_completions (
  user_id uuid not null references public.profiles(id) on delete cascade,
  quiz_date date not null,
  meme_short_id text not null check (char_length(meme_short_id) between 1 and 32),
  correct boolean not null,
  completed_at timestamptz not null default now(),
  primary key (user_id, quiz_date)
);

create index if not exists daily_meme_quiz_completions_date_idx
  on public.daily_meme_quiz_completions (quiz_date);

alter table public.daily_meme_quiz_completions enable row level security;

revoke all on table public.daily_meme_quiz_completions from public, anon, authenticated;
grant select on table public.daily_meme_quiz_completions to authenticated;

drop policy if exists daily_meme_quiz_completions_self_read on public.daily_meme_quiz_completions;
create policy daily_meme_quiz_completions_self_read
  on public.daily_meme_quiz_completions
  for select using (user_id = (select auth.uid()));

create or replace function public.get_daily_meme_quiz_status()
returns table (
  quiz_date date,
  completed_at timestamptz,
  correct boolean,
  current_streak integer,
  best_streak integer,
  total_days integer
)
language plpgsql
stable
security definer
set search_path = pg_catalog, public
as $function$
declare
  v_uid uuid := auth.uid();
  v_today date := (now() at time zone 'Asia/Seoul')::date;
  v_completed_at timestamptz;
  v_correct boolean;
  v_streak integer := 0;
  v_best integer := 0;
  v_total integer := 0;
  v_cursor date;
begin
  if v_uid is null then
    raise exception using errcode = '42501', message = 'login_required';
  end if;

  select c.completed_at, c.correct
    into v_completed_at, v_correct
    from public.daily_meme_quiz_completions c
   where c.user_id = v_uid
     and c.quiz_date = v_today;

  -- A streak stays alive until the user misses a full KST day: before today's
  -- answer it is counted from yesterday.
  v_cursor := case when v_completed_at is null then v_today - 1 else v_today end;
  loop
    exit when not exists (
      select 1
        from public.daily_meme_quiz_completions c
       where c.user_id = v_uid
         and c.quiz_date = v_cursor
    );
    v_streak := v_streak + 1;
    v_cursor := v_cursor - 1;
  end loop;

  -- Gaps-and-islands: consecutive dates share (date - row_number).
  select coalesce(max(run.days), 0)::integer, coalesce(sum(run.days), 0)::integer
    into v_best, v_total
    from (
      select count(*) as days
        from (
          select c.quiz_date,
                 c.quiz_date - (row_number() over (order by c.quiz_date))::integer as island
            from public.daily_meme_quiz_completions c
           where c.user_id = v_uid
        ) numbered
       group by numbered.island
    ) run;

  return query select
    v_today,
    v_completed_at,
    v_correct,
    v_streak,
    greatest(v_best, v_streak),
    v_total;
end;
$function$;

revoke all on function public.get_daily_meme_quiz_status() from public, anon, authenticated;
grant execute on function public.get_daily_meme_quiz_status() to authenticated;

-- Only the first answer of the KST day counts; repeats are idempotent no-ops.
-- The date always comes from the server clock, never from the client.
create or replace function public.complete_daily_meme_quiz(p_meme_short_id text, p_correct boolean)
returns table (
  quiz_date date,
  completed_at timestamptz,
  correct boolean,
  current_streak integer,
  best_streak integer,
  total_days integer
)
language plpgsql
security definer
set search_path = pg_catalog, public
as $function$
declare
  v_uid uuid := auth.uid();
  v_today date := (now() at time zone 'Asia/Seoul')::date;
begin
  if v_uid is null then
    raise exception using errcode = '42501', message = 'login_required';
  end if;
  if p_meme_short_id is null or btrim(p_meme_short_id) = '' or char_length(p_meme_short_id) > 32 then
    raise exception using errcode = '22023', message = 'meme_short_id_invalid';
  end if;
  if p_correct is null then
    raise exception using errcode = '22023', message = 'correct_required';
  end if;

  insert into public.daily_meme_quiz_completions as completion (
    user_id,
    quiz_date,
    meme_short_id,
    correct
  ) values (
    v_uid,
    v_today,
    btrim(p_meme_short_id),
    p_correct
  ) on conflict on constraint daily_meme_quiz_completions_pkey do nothing;

  return query select * from public.get_daily_meme_quiz_status();
end;
$function$;

revoke all on function public.complete_daily_meme_quiz(text, boolean) from public, anon, authenticated;
grant execute on function public.complete_daily_meme_quiz(text, boolean) to authenticated;
